#!/usr/bin/env bash
# Post an "action needed" message to this project's Discord channel and @mention a person.
# Webhook and who-can-be-pinged come from Heka Vault at run time (see config.env); nothing
# personal or secret is stored in the repo. Generated by heka automation/scripts/project-discord-ask.py.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=/dev/null
source "$HERE/config.env"

usage() {
  cat <<EOF
Usage: $(basename "$0") --title TEXT --body TEXT [options]

  --level fyi|action|blocked   default action. fyi never pings.
  --to NAME[,NAME]             who to ping (default eric). Must be allowed for this project.
  --title TEXT                 one line: what you need
  --body TEXT|-                why, what you tried, what happens next (- reads stdin)
  --link URL                   PR, issue, T3 thread, deploy (recommended)
  --project SLUG               post to a sub-project channel (${ASK_SUBPROJECTS:-none here})
  --dry-run                    print the payload, send nothing
  --force                      send even if the same title was sent in the last 24h
  --who                        list the people this project can ping
EOF
}

level=action to="" title="" body="" link="" sub="" dry=0 force=0 who=0
while (($#)); do
  case "$1" in
    --level) level="$2"; shift 2 ;;
    --to) to="$2"; shift 2 ;;
    --title) title="$2"; shift 2 ;;
    --body) body="$2"; shift 2 ;;
    --link) link="$2"; shift 2 ;;
    --project) sub="$2"; shift 2 ;;
    --dry-run) dry=1; shift ;;
    --force) force=1; shift ;;
    --who) who=1; shift ;;
    -h|--help) usage; exit 0 ;;
    *) echo "unknown argument: $1" >&2; usage >&2; exit 2 ;;
  esac
done
[[ "$body" == "-" ]] && body="$(cat)"

case "$level" in fyi|action|blocked) ;; *) echo "--level must be fyi, action or blocked" >&2; exit 2 ;; esac
if [[ -n "$sub" && " ${ASK_SUBPROJECTS:-} " != *" $sub "* ]]; then
  echo "--project $sub is not a sub-project of $ASK_SLUG (allowed: ${ASK_SUBPROJECTS:-none})" >&2; exit 2
fi
if ((!who)) && [[ -z "$title" || -z "$body" ]]; then usage >&2; exit 2; fi

vault_path="$ASK_VAULT_PATH${sub:+/$sub}"
webhook="${DISCORD_WEBHOOK:-}"
people="${DISCORD_ASK_PEOPLE:-}"
if [[ -z "$webhook" || -z "$people" ]]; then
  creds="$HOME/.config/heka-vault/${ASK_VAULT_PROJECT}.env"
  [[ -f "$creds" ]] || creds="$HOME/.config/heka-vault/admin.env"
  if [[ ! -f "$creds" ]]; then
    echo "No Heka Vault key for '$ASK_VAULT_PROJECT' on $(hostname -s). Tell the operator in your reply instead." >&2
    exit 3
  fi
  dotenv="$(
    set -a; source "$creds"; set +a
    curl -fsS -H "Authorization: Bearer $HEKA_VAULT_TOKEN" \
      "$HEKA_VAULT_URL/api/v1/projects/$ASK_VAULT_PROJECT/secrets?env=dev&path=$(jq -rn --arg v "$vault_path" '$v|@uri')&format=dotenv"
  )" || { echo "Heka Vault read failed for $ASK_VAULT_PROJECT:$vault_path" >&2; exit 3; }
  pick() { sed -n "s/^$1=//p" <<<"$dotenv" | sed -e "s/^'//" -e "s/'\$//" -e 's/^"//' -e 's/"$//'; }
  webhook="$(pick DISCORD_WEBHOOK)"
  people="$(pick DISCORD_ASK_PEOPLE)"
fi
[[ -n "$webhook" && -n "$people" ]] || { echo "Vault $ASK_VAULT_PROJECT:$vault_path is missing DISCORD_WEBHOOK or DISCORD_ASK_PEOPLE" >&2; exit 3; }

if ((who)); then tr ',' '\n' <<<"$people" | cut -d= -f1; exit 0; fi

ids=()
if [[ "$level" != fyi ]]; then
  for name in $(tr ',' ' ' <<<"${to:-eric}"); do
    id="$(tr ',' '\n' <<<"$people" | sed -n "s/^$name=//p")"
    [[ -n "$id" ]] || { echo "can't ping '$name' from $ASK_SLUG (allowed: $(tr ',' '\n' <<<"$people" | cut -d= -f1 | paste -sd' '))" >&2; exit 2; }
    ids+=("$id")
  done
fi

state="${XDG_STATE_HOME:-$HOME/.local/state}/discord-ask"
key="$(printf '%s|%s|%s' "$ASK_SLUG" "$sub" "$title" | sha256sum | cut -c1-16)"
now="$(date +%s)"
if ((!force && !dry)) && [[ -f "$state/sent" ]] &&
  awk -v k="$key" -v t="$((now - 86400))" '$1 == k && $2 > t { f = 1 } END { exit !f }' "$state/sent"; then
  echo "SKIP: \"$title\" was already sent in the last 24h (use --force only if something changed)"
  exit 0
fi

repo="$(basename "$(git rev-parse --show-toplevel 2>/dev/null || pwd)")"
branch="$(git branch --show-current 2>/dev/null || true)"
payload="$(jq -nc \
  --arg user "${sub:-$ASK_SLUG} agent" --arg level "$level" --arg title "$title" --arg body "$body" \
  --arg link "$link" --arg footer "$(hostname -s) · $repo${branch:+@$branch}" \
  --arg ts "$(date -u +%Y-%m-%dT%H:%M:%SZ)" '
  $ARGS.positional as $ids
  | {fyi: "FYI", action: "Action needed", blocked: "Blocked"}[$level] as $label
  | {
      username: $user,
      content: ((($ids | map("<@\(.)>") | join(" ")) + " " + $label) | ltrimstr(" ")),
      allowed_mentions: {parse: [], users: $ids},
      embeds: [({
        title: ("\($label): \($title)" | .[0:256]),
        description: ($body | .[0:4000]),
        color: {fyi: 5793266, action: 16705372, blocked: 15548997}[$level],
        footer: {text: $footer},
        timestamp: $ts
      } + (if $link == "" then {} else {url: $link} end))]
    }' --args "${ids[@]}")"

if ((dry)); then jq . <<<"$payload"; exit 0; fi

curl -fsS -o /dev/null -H 'content-type: application/json' --data-binary "$payload" "$webhook" ||
  { echo "Discord post failed" >&2; exit 4; }
mkdir -p "$state"
echo "$key $now" >>"$state/sent"
echo "sent $level to ${sub:-#$ASK_CHANNEL}${ids[*]:+ (pinged ${to:-eric})}"
